/* ما يصل من مرصاد:
     $json.body.structure  اسم المنشأة
     $json.body.notes      ملاحظات الفنّي
     $json.body.date / type / engineer / section
     $binary.file0, file1, …   الصور والتقارير

   استبدل ما تحت هذا السطر بمنطق وكيلك، واحرص أن يخرج بهذا الشكل.
   الحقل title وحده إلزامي; والباقي يُعرض إن وُجد ويُطوى إن غاب. */

const body = $json.body || {};
const files = Object.keys($binary || {});

return [{
  json: {
    accuracy: 90,
    findings: [
      {
        title: 'ملاحظة تجريبية من سير العمل',
        titleEn: 'Test finding from the workflow',
        location: body.structure || 'غير محدّد',
        locationEn: body.structure || 'unspecified',
        severity: 'medium',
        confidence: 90,
        note: `وصل ${files.length} ملف · الملاحظات: ${body.notes || '—'}`
      }
    ]
  }
}];
